{
  "$$\\mathcal{I}$$": [1, 2, 3, 4],
  "$$\\mathcal{K}$$": ["heavy", "light"],
  "$$d_i$$": {
    "1": 450,
    "2": 480,
    "3": 540,
    "4": 600
  },
  "$$p_{ik}$$": {
    "heavy": {
      "1": 0.03,
      "2": 0.10,
      "3": 0.05,
      "4": 0.05
    },
    "light": {
      "1": 0.08,
      "2": 0.11,
      "3": 0.12,
      "4": 0.09
    }
  },
  "$$B_k$$": {
    "heavy": 28,
    "light": 12
  },
  "$$F^{\\max}$$": 10000,
  "$$r_k^{\\text{load}}$$": {
    "heavy": 2,
    "light": 3
  },
  "$$r^{\\text{empty}}$$": 4,
  "$$f^{\\text{oh}}$$": 100,
  "$$m$$": 2
}
